def missing_chat_template_3(required,present):
    if type(required) is not tuple or type(present) is not tuple: raise TypeError('container_invalid')
    if any(type(value) is not str for value in required+present): raise TypeError('item_invalid')
    if any(not value.strip() for value in required+present): raise ValueError('item_blank')
